export function countryCodeToFlag(cc: string): string {
  if (!cc || cc.length !== 2) return '🌐';
  const code = cc.toUpperCase();
  const base = 127397;
  return String.fromCodePoint(base + code.charCodeAt(0), base + code.charCodeAt(1));
}

const REGION_LABELS: Record<ComputerTimezoneRegion, string> = {
  america: 'Américas',
  europe: 'Europa',
  asia: 'Ásia',
  africa: 'África',
  oceania_pacific: 'Oceania / Pacífico',
  atlantic_indian_poles: 'Atlântico / Índico / Polos',
  global_posix: 'Global / POSIX / Etc',
};

function classifyRegion(canonicalId: string): ComputerTimezoneRegion {
  if (canonicalId.startsWith('America/')) return 'america';
  if (canonicalId.startsWith('Europe/')) return 'europe';
  if (canonicalId.startsWith('Asia/')) return 'asia';
  if (canonicalId.startsWith('Africa/')) return 'africa';
  if (canonicalId.startsWith('Australia/') || canonicalId.startsWith('Pacific/')) return 'oceania_pacific';
  if (
    canonicalId.startsWith('Atlantic/') ||
    canonicalId.startsWith('Indian/') ||
    canonicalId.startsWith('Antarctica/') ||
    canonicalId.startsWith('Arctic/')
  ) {
    return 'atlantic_indian_poles';
  }
  return 'global_posix';
}

