function formatCityName(ianaId: string): string {
  if (!ianaId.includes('/')) {
    if (ianaId === 'EST5EDT') return 'EUA Leste (POSIX EST5EDT)';
    if (ianaId === 'CST6CDT') return 'EUA Central (POSIX CST6CDT)';
    if (ianaId === 'MST7MDT') return 'EUA Montanhas (POSIX MST7MDT)';
    if (ianaId === 'PST8PDT') return 'EUA Pacífico (POSIX PST8PDT)';
    return ianaId;
  }
  if (ianaId === 'America/Bahia') return 'Salvador (Bahia)';
  if (ianaId === 'America/Recife') return 'Recife (PE)';
  if (ianaId === 'America/Manaus') return 'Manaus (AM)';
  if (ianaId === 'America/Cuiaba') return 'Cuiabá (MT)';
  if (ianaId === 'America/Campo_Grande') return 'Campo Grande (MS)';
  if (ianaId === 'America/Belem') return 'Belém (PA)';
  if (ianaId === 'America/Santarem') return 'Altamira / Oeste Paraense (Santarém - PA)';
  if (ianaId === 'America/Araguaina') return 'Palmas / Araguaína (TO)';
  const parts = ianaId.split('/');
  const leaf = parts[parts.length - 1].replace(/_/g, ' ');
  if (parts.length >= 3) {
    const parent = parts[parts.length - 2].replace(/_/g, ' ');
    return `${leaf} (${parent})`;
  }
  return leaf;
}

function probeRuntimeOffset(tz: string, date: Date): number {
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    });
    const parts = fmt.formatToParts(date);
    const get = (t: string) => parts.find((p) => p.type === t)?.value || '0';
    let hr = parseInt(get('hour'), 10);
    if (hr === 24) hr = 0;
    const utc = Date.UTC(
      parseInt(get('year'), 10),
      parseInt(get('month'), 10) - 1,
      parseInt(get('day'), 10),
      hr,
      parseInt(get('minute'), 10),
      parseInt(get('second'), 10)
    );
    return Number((Math.round((utc - date.getTime()) / 60000) / 60).toFixed(2));
  } catch {
    return 0;
  }
}

function buildComputerTimezones(): ComputerTimezoneEntry[] {
  const seenIds = new Set<string>();
  const entries: ComputerTimezoneEntry[] = [];

  for (const [
    id,
    canonicalId,
    isCan,
    cc,
    countryRaw,
    lat,
    lon,
    stdOff,
    altOff,
    hasDstNum,
    comment,
  ] of RAW_COMPUTER_TIMEZONES) {
    seenIds.add(id);
    const region = classifyRegion(canonicalId);
    const isPosixGlobal = region === 'global_posix' || id.startsWith('Etc/') || !id.includes('/');
    const countryName = COUNTRY_PT_MAP[countryRaw] || countryRaw || (isPosixGlobal ? 'Global / Sistema' : '');
    entries.push({
      id,
      canonicalId,
      isCanonical: isCan === 1,
      versionLabel:
        isCan === 1
          ? isPosixGlobal
            ? 'POSIX / Global'
            : 'Versão Canônica (Atual)'
          : 'Versão Legada / Alias',
      cityName: formatCityName(id),
      region,
      regionLabel: REGION_LABELS[region],
      countryCode: cc,
      countryName,
      flagEmoji: cc ? countryCodeToFlag(cc) : '🌐',
      latitude: lat,
      longitude: lon,
      stdOffsetHours: stdOff,
      altOffsetHours: altOff,
      hasDst: hasDstNum === 1,
      comment,
    });
  }

  try {
    const intlAny = Intl as unknown as { supportedValuesOf?: (key: string) => string[] };
    const runtimeZones = intlAny.supportedValuesOf?.('timeZone') || [];
    const jan = new Date(Date.UTC(2026, 0, 1, 12, 0, 0));
    const jul = new Date(Date.UTC(2026, 6, 1, 12, 0, 0));
    for (const tz of runtimeZones) {
      if (seenIds.has(tz)) continue;
      seenIds.add(tz);
      const janOff = probeRuntimeOffset(tz, jan);
      const julOff = probeRuntimeOffset(tz, jul);
      const region = classifyRegion(tz);
      entries.push({
        id: tz,
        canonicalId: tz,
        isCanonical: true,
        versionLabel: region === 'global_posix' ? 'POSIX / Global' : 'Versão Canônica (Atual)',
        cityName: formatCityName(tz),
        region,
        regionLabel: REGION_LABELS[region],
        countryCode: '',
        countryName: 'Sistema Local (Intl)',
        flagEmoji: '🖥️',
        latitude: null,
        longitude: null,
        stdOffsetHours: Math.min(janOff, julOff),
        altOffsetHours: Math.max(janOff, julOff),
        hasDst: Math.abs(janOff - julOff) > 0.01,
        comment: 'Detectado via Intl do navegador',
      });
    }
  } catch {
    // Ignore if browser lacks supportedValuesOf
  }

  return entries;
}

export const COMPUTER_TIMEZONES: ComputerTimezoneEntry[] = buildComputerTimezones();

function buildCityGroups(entries: ComputerTimezoneEntry[]): CityTimezoneGroup[] {
  const byCanonical = new Map<string, ComputerTimezoneEntry[]>();
  for (const e of entries) {
    const bucket = byCanonical.get(e.canonicalId);
    if (bucket) bucket.push(e);
    else byCanonical.set(e.canonicalId, [e]);
  }

  const groups: CityTimezoneGroup[] = [];
  byCanonical.forEach((versions, canonicalId) => {
    const sortedVersions = [...versions].sort((a, b) => {
      if (a.id === canonicalId) return -1;
      if (b.id === canonicalId) return 1;
      return a.id.localeCompare(b.id);
    });
    const primary = sortedVersions[0];
    groups.push({
      canonicalId,
      cityName: primary.cityName,
      countryCode: primary.countryCode,
      countryName: primary.countryName,
      flagEmoji: primary.flagEmoji,
      region: primary.region,
      regionLabel: primary.regionLabel,
      latitude: primary.latitude,
      longitude: primary.longitude,
      stdOffsetHours: primary.stdOffsetHours,
      altOffsetHours: primary.altOffsetHours,
      hasDst: primary.hasDst,
      comment: primary.comment,
      primary,
      versions: sortedVersions,
    });
  });

  return groups.sort((a, b) => a.cityName.localeCompare(b.cityName, 'pt-BR'));
}

export const CITY_TIMEZONE_GROUPS: CityTimezoneGroup[] = buildCityGroups(COMPUTER_TIMEZONES);

export const COMPUTER_TZ_STATS = {
  totalOptions: COMPUTER_TIMEZONES.length,
  canonicalCities: CITY_TIMEZONE_GROUPS.length,
  legacyVersions: COMPUTER_TIMEZONES.filter((z) => !z.isCanonical).length,
  citiesWithMultipleVersions: CITY_TIMEZONE_GROUPS.filter((g) => g.versions.length > 1).length,
  dstCities: CITY_TIMEZONE_GROUPS.filter((g) => g.hasDst).length,
};
